import{_ as e,o,c as n,ah as i}from"./chunks/framework.DI21z1I4.js";const a="/projects/miniHexa/en/v1.1/assets/image1.BWNuGz6Q.jpeg",s="data:image/png;base64,",r="/projects/miniHexa/en/v1.1/assets/image3.DxZ31MBs.jpeg",l="/projects/miniHexa/en/v1.1/assets/image4.BS7RYPyL.png",g="/projects/miniHexa/en/v1.1/assets/image5.D5nlIDHV.png",c="/projects/miniHexa/en/v1.1/assets/image6.DIgTny5G.png",p="/projects/miniHexa/en/v1.1/assets/image7.BpTK80BZ.png",d="/projects/miniHexa/en/v1.1/assets/image8.Bn9XwW2v.png",m="data:image/png;base64,",h="/projects/miniHexa/en/v1.1/assets/image10.BGOSFPbx.png",A="/projects/miniHexa/en/v1.1/assets/image11.DBgnzDjD.png",x="/projects/miniHexa/en/v1.1/assets/image12.BnMAFP3E.png",y="/projects/miniHexa/en/v1.1/assets/image13.BG8z4cdU.png",u="/projects/miniHexa/en/v1.1/assets/image14.8Yv2VCEu.png",w="/projects/miniHexa/en/v1.1/assets/image15.D5VF33pp.png",I="/projects/miniHexa/en/v1.1/assets/image16.BIDgNwjE.png",f="/projects/miniHexa/en/v1.1/assets/image17.D-N8qXLH.png",v="/projects/miniHexa/en/v1.1/assets/image18.DyiZJ-mv.png",D="/projects/miniHexa/en/v1.1/assets/image19.De5BpmY4.png",b="/projects/miniHexa/en/v1.1/assets/image20.CsWzh07w.png",B="/projects/miniHexa/en/v1.1/assets/image21._VltM4AO.png",P="/projects/miniHexa/en/v1.1/assets/image22.dUCBQMaz.png",E="/projects/miniHexa/en/v1.1/assets/image23.CiKRrdo6.png",Q="/projects/miniHexa/en/v1.1/assets/image24.DRD7nWWk.png",H="/projects/miniHexa/en/v1.1/assets/image2.XOWjlBkt.jpeg",C="data:image/png;base64,",V="/projects/miniHexa/en/v1.1/assets/image27.DVYQg0xi.png",O="/projects/miniHexa/en/v1.1/assets/image28.wrj0Iu5b.png",W="/projects/miniHexa/en/v1.1/assets/image7.DAseRU5M.png",K=JSON.parse('{"title":"2. APP Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.APP_Control.md","filePath":"docs/2.APP_Control.md"}'),G={name:"docs/2.APP_Control.md"};function z(U,t,q,j,k,T){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="_2-app-control" tabindex="-1">2. APP Control <a class="header-anchor" href="#_2-app-control" aria-label="Permalink to &quot;2. APP Control&quot;">​</a></h1><p>The miniHexa comes with the App control program pre-installed, so you can start using it right away. The instructions below use Android as an example.</p><h2 id="_2-1-app-installation" tabindex="-1">2.1 App Installation <a class="header-anchor" href="#_2-1-app-installation" aria-label="Permalink to &quot;2.1 App Installation&quot;">​</a></h2><p>iOS users: Download the app <a href="https://apps.apple.com/us/app/wonderbot-robot/id1519146341" target="_blank" rel="noreferrer">Wonderbot</a> in the App Store.</p><p>Android users: You can find the <a href="https://play.google.com/store/apps/details?id=com.Wonder.bot" target="_blank" rel="noreferrer">Wonderbot</a> installation package in the same directory as this section or in <a href="./Appendix.html">Appendix-&gt;App Installation Package</a>, then install it on your phone.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li>Ensure that both Bluetooth and Location Services are enabled in your phone&#39;s settings before launching the app.</li><li>Do not pair the device manually via system Bluetooth settings. Instead, use the Bluetooth button within the app to initiate pairing and connection.</li></ul></section><p>(1) Turn on the miniHexa power switch.</p><img loading="lazy" height="600" width="1200" src="'+a+'" class="common_img"><p>(2) Open the Wonderbot app, tap the icon <img loading="lazy" height="78" src="'+s+'" width="70px"> in the top-left corner, and select your robot model — miniHexa.</p><img loading="lazy" height="570" width="1235" src="'+r+'" class="common_img"><p>(3) Once selected, enter the control interface, tap the blinking icon <img loading="lazy" height="97" src="'+l+'" width="70px"> in the top-right corner, and select <strong>miniHexa</strong> from the Bluetooth device list.<img loading="lazy" height="725" width="1618" src="'+g+'" class="common_img"></p><p>If miniHexa does not appear in the list at first, tap <strong>&quot;Searching Again&quot;</strong> to refresh the list.</p><p>(4) Once connected, the Bluetooth icon in the top-right corner will stay solid, and the battery level will be displayed on the left side of the screen.</p><img loading="lazy" height="724" width="1617" src="'+c+'" class="common_img"><h2 id="_2-2-function-introduction" tabindex="-1">2.2 Function Introduction <a class="header-anchor" href="#_2-2-function-introduction" aria-label="Permalink to &quot;2.2 Function Introduction&quot;">​</a></h2><p>In the basic control mode, you can manage miniHexa&#39;s movement, posture adjustment, ultrasonic obstacle avoidance, action group execution, self-balancing, height adjustment, and reset.</p><p>This interface is divided into two sections:</p><img loading="lazy" height="730" width="1615" src="'+p+'" class="common_img"><ul><li><strong>Menu Bar</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="154" width="173" src="'+d+'"></td><td style="text-align:left;">Return to the main screen to select the robot type</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="69" width="173" src="'+m+'"></td><td style="text-align:left;">Display the current battery level of miniHexa in real time</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="133" width="173" src="'+h+'"></td><td style="text-align:left;">View live video from the ESP32S3 vision module</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="119" width="173" src="'+A+'"></td><td style="text-align:left;">Bluetooth connection, blinking when disconnected, solid when connected</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="141" width="173" src="'+x+'"></td><td style="text-align:left;">Additional information</td></tr></tbody></table><ul><li><strong>Control Area</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Icon</strong></th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="233" src="'+y+'" width="200px"></td><td style="text-align:left;">Control miniHexa&#39;s movement</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="400" src="'+u+'" width="200px"></td><td style="text-align:left;">Control the planar position of miniHexa&#39;s body center</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="96" src="'+w+'" width="200px"></td><td style="text-align:left;">Switch between different control modes</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="159" src="'+I+'" width="200px"></td><td style="text-align:left;">Display distance measured by the ultrasonic sensor</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="97" src="'+f+'" width="200px"></td><td style="text-align:left;">Toggle ultrasonic obstacle avoidance on/off</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="181" src="'+v+'" width="200px"></td><td style="text-align:left;">Control miniHexa&#39;s Euler angles using the phone&#39;s gyroscope</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="179" src="'+D+'" width="200px"></td><td style="text-align:left;">Toggle IMU self-balancing mode on/off</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="164" src="'+b+'" width="200px"></td><td style="text-align:left;">Execute predefined action groups</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="97" src="'+B+'" width="200px"></td><td style="text-align:left;">Toggle ultrasonic RGB lights on/off</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="51" src="'+P+'" width="200px"></td><td style="text-align:left;">Adjust the color of the ultrasonic RGB lights</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="293" src="'+E+'" width="200px"></td><td style="text-align:left;">Adjust miniHexa&#39;s standing height<br>Value range: 0 ~ 30</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="150" src="'+Q+'" width="200px"></td><td style="text-align:left;">Left/right sides: control miniHexa&#39;s turning.<br>Center: reset to upright position</td></tr></tbody></table><h2 id="_2-3-app-program-download-instructions-optional" tabindex="-1">2.3 App Program Download Instructions (Optional) <a class="header-anchor" href="#_2-3-app-program-download-instructions-optional" aria-label="Permalink to &quot;2.3 App Program Download Instructions (Optional)&quot;">​</a></h2><p><a href="https://drive.google.com/drive/folders/1mNnrcIngyjdzhke1Y8t24vxM5DLOykgW?usp=sharing" target="_blank" rel="noreferrer">Source Code</a></p><p>The miniHexa comes with the App control program pre-installed. Downloading other feature&#39;s program will overwrite the existing App control functionality. To use this feature again, you will need to re-download the App program.</p><p>(1) Connect miniHexa to your computer using a Type-C data cable.</p><img loading="lazy" height="800" width="1200" src="'+H+'" class="common_img"><p>(2) Open the program file located at: <code>2. App Control-&gt;2.3 App Program Files-&gt;remote-&gt;remote.ino</code></p><img loading="lazy" height="28" width="384" src="'+C+'" class="common_img"><p>(3) Select the development board model when you open the program, and the specific model is shown in the figure below.</p><img loading="lazy" height="39" width="431" src="'+V+'" class="common_img"><p>(4) In the menu bar, click <strong>&quot;Tools&quot;</strong>, and choose the corresponding ESP32 controller configuration as illustrated.</p><img loading="lazy" height="785" width="831" src="'+O+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Make sure to set the correct controller configuration before uploading the program.</p></section><p>(5) Click <strong>&quot;Compile&quot;</strong> first, then click <strong>&quot;Upload&quot;</strong>. After the upload is completed, the program download is completed if the following interface appears in the output box below the software.</p><img loading="lazy" height="174" width="1057" src="'+W+'" class="common_img">',36)])])}const F=e(G,[["render",z]]);export{K as __pageData,F as default};
